/// The struct's bytes in hex.
fn hex<T>(v: &MaybeUninit<T>) -> String {
    // SAFETY: `v` was zeroed in place and only written through its fields, so every byte
    // (padding included) is initialised.
    let bytes = unsafe { core::slice::from_raw_parts(v.as_ptr().cast::<u8>(), size_of::<T>()) };
    bytes.iter().map(|b| format!("{b:02x}")).collect()
}

