/// Every line, in `layout.c`'s order.
pub fn lines() -> Vec<String> {
    let mut out = vec![format!("V {HEADER_VERSION}")];
    out.extend(TYPES.iter().map(|(n, s, a)| format!("S {n} {s} {a}")));
    out.extend(FIELDS.iter().map(|(t, m, o)| format!("F {t}.{m} {o}")));
    out.extend(bitfields());
    out
}
